import { INTERCEPTION_ROUTE_MARKERS } from '../../shared/lib/router/utils/interception-routes'
import type { DynamicParamTypes } from './types'

/**
 * Parse dynamic route segment to type of parameter
 */
export function getSegmentParam(segment: string): {
  param: string
  type: DynamicParamTypes
} | null {
  const interceptionMarker = INTERCEPTION_ROUTE_MARKERS.find((marker) =>
    segment.startsWith(marker)
  )

  // if an interception marker is part of the path segment, we need to jump ahead
  // to the relevant portion for param parsing
  if (interceptionMarker) {
    segment = segment.slice(interceptionMarker.length)
  }

  if (segment.startsWith('[[...') && segment.endsWith(']]')) {
    return {
      // TODO-APP: Optional catchall does not currently work with parallel routes,
      // so for now aren't handling a potential interception marker.
      type: 'optional-catchall',
      param: segment.slice(5, -2),
    }
  }

  if (segment.startsWith('[...') && segment.endsWith(']')) {
    return {
      type: interceptionMarker ? 'catchall-intercepted' : 'catchall',
      param: segment.slice(4, -1),
    }
  }

  if (segment.startsWith('[') && segment.endsWith(']')) {
    return {
      type: interceptionMarker ? 'dynamic-intercepted' : 'dynamic',
      param: segment.slice(1, -1),
    }
  }

  return null
}
const CSP_NONCE_SOURCE_REGEX = /^'nonce-([A-Za-z0-9+/_-]+={0,2})'$/

export function getScriptNonceFromHeader(
  cspHeaderValue: string
): string | undefined {
  const directives = cspHeaderValue
    // Directives are split by ';'.
    .split(';')
    .map((directive) => directive.trim())

  // First try to find the directive for the 'script-src', otherwise try to
  // fallback to the 'default-src'.
  const directive =
    directives.find((dir) => dir.startsWith('script-src')) ||
    directives.find((dir) => dir.startsWith('default-src'))

  // If no directive could be found, then we're done.
  if (!directive) {
    return
  }

  // Extract the first valid nonce from the directive. Malformed nonces are
  // ignored so the request can continue without a nonce instead of failing.
  for (const source of directive.split(/\s+/).slice(1)) {
    const match = source.trim().match(CSP_NONCE_SOURCE_REGEX)

    if (match) {
      return match[1]
    }
  }
}
import type { FlightRouterState } from './types'
import { flightRouterStateSchema } from './types'
import { assert } from 'next/dist/compiled/superstruct'

export function parseAndValidateFlightRouterState(
  stateHeader: string | string[]
): FlightRouterState
export function parseAndValidateFlightRouterState(
  stateHeader: undefined
): undefined
export function parseAndValidateFlightRouterState(
  stateHeader: string | string[] | undefined
): FlightRouterState | undefined
export function parseAndValidateFlightRouterState(
  stateHeader: string | string[] | undefined
): FlightRouterState | undefined {
  if (typeof stateHeader === 'undefined') {
    return undefined
  }
  if (Array.isArray(stateHeader)) {
    throw new Error(
      'Multiple router state headers were sent. This is not allowed.'
    )
  }

  // We limit the size of the router state header to ~40kb. This is to prevent
  // a malicious user from sending a very large header and slowing down the
  // resolving of the router state.
  // This is around 2,000 nested or parallel route segment states:
  // '{"children":["",{}]}'.length === 20.
  if (stateHeader.length > 20 * 2000) {
    throw new Error('The router state header was too large.')
  }

  try {
    const state = JSON.parse(decodeURIComponent(stateHeader))
    assert(state, flightRouterStateSchema)
    return state
  } catch {
    throw new Error('The router state header was sent but could not be parsed.')
  }
}
import type { LoaderTree } from '../lib/app-dir-module'
import { HasLoadingBoundary, type FlightRouterState } from './types'
import type { GetDynamicParamFromSegment } from './app-render'
import { addSearchParamsIfPageSegment } from '../../shared/lib/segment'

function createFlightRouterStateFromLoaderTreeImpl(
  [segment, parallelRoutes, { layout, loading }]: LoaderTree,
  getDynamicParamFromSegment: GetDynamicParamFromSegment,
  searchParams: any,
  includeHasLoadingBoundary: boolean,
  didFindRootLayout: boolean
): FlightRouterState {
  const dynamicParam = getDynamicParamFromSegment(segment)
  const treeSegment = dynamicParam ? dynamicParam.treeSegment : segment

  const segmentTree: FlightRouterState = [
    addSearchParamsIfPageSegment(treeSegment, searchParams),
    {},
  ]

  // Mark the first segment that has a layout as the "root" layout
  if (!didFindRootLayout && typeof layout !== 'undefined') {
    didFindRootLayout = true
    segmentTree[4] = true
  }

  let childHasLoadingBoundary = false
  const children: FlightRouterState[1] = {}
  Object.keys(parallelRoutes).forEach((parallelRouteKey) => {
    const child = createFlightRouterStateFromLoaderTreeImpl(
      parallelRoutes[parallelRouteKey],
      getDynamicParamFromSegment,
      searchParams,
      includeHasLoadingBoundary,
      didFindRootLayout
    )
    if (
      includeHasLoadingBoundary &&
      child[5] !== HasLoadingBoundary.SubtreeHasNoLoadingBoundary
    ) {
      childHasLoadingBoundary = true
    }
    children[parallelRouteKey] = child
  })
  segmentTree[1] = children

  if (includeHasLoadingBoundary) {
    // During a route tree prefetch, the FlightRouterState includes whether a
    // tree has a loading boundary. The client uses this to determine if it can
    // skip the data prefetch request — if `hasLoadingBoundary` is `false`, the
    // data prefetch response will be empty, so there's no reason to request it.
    // NOTE: It would be better to accumulate this while building the loader
    // tree so we don't have to keep re-deriving it, but since this won't be
    // once PPR is enabled everywhere, it's not that important.
    segmentTree[5] = loading
      ? HasLoadingBoundary.SegmentHasLoadingBoundary
      : childHasLoadingBoundary
        ? HasLoadingBoundary.SubtreeHasLoadingBoundary
        : HasLoadingBoundary.SubtreeHasNoLoadingBoundary
  }

  return segmentTree
}

export function createFlightRouterStateFromLoaderTree(
  loaderTree: LoaderTree,
  getDynamicParamFromSegment: GetDynamicParamFromSegment,
  searchParams: any
) {
  const includeHasLoadingBoundary = false
  const didFindRootLayout = false
  return createFlightRouterStateFromLoaderTreeImpl(
    loaderTree,
    getDynamicParamFromSegment,
    searchParams,
    includeHasLoadingBoundary,
    didFindRootLayout
  )
}

export function createRouteTreePrefetch(
  loaderTree: LoaderTree,
  getDynamicParamFromSegment: GetDynamicParamFromSegment
): FlightRouterState {
  // Search params should not be added to page segment's cache key during a
  // route tree prefetch request, because they do not affect the structure of
  // the route. The client cache has its own logic to handle search params.
  const searchParams = {}
  // During a route tree prefetch, we include `hasLoadingBoundary` in
  // the response.
  const includeHasLoadingBoundary = true
  const didFindRootLayout = false
  return createFlightRouterStateFromLoaderTreeImpl(
    loaderTree,
    getDynamicParamFromSegment,
    searchParams,
    includeHasLoadingBoundary,
    didFindRootLayout
  )
}
